const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2023-07-08';
  const start_date = ee.Date(date).advance(-1, 'day'); // 1-day window
  const end_date = ee.Date(date).advance(1, 'day');

  // Approximate coordinates for the two locations on Lake Ijssel
  // Kornwerderzand is at the northern end of the Afsluitdijk, on Lake Ijssel side.
  const point_kornwerderzand = ee.Geometry.Point([5.3340, 53.0760]); // Just off Kornwerderzand, in Lake Ijssel
  // Afsluitdijk near its southern end (Den Oever side), in Lake Ijssel.
  const point_afsluitdijk = ee.Geometry.Point([5.1110, 52.9240]); // Just off Den Oever, in Lake Ijssel

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(start_date, end_date)
    .filterBounds(point_kornwerderzand.union(point_afsluitdijk))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Keep relatively clear images

  const collection_size = await collection.size().getInfo();
  console.log(`Initial Sentinel-2 images found: ${collection_size}`);

  if (collection_size === 0) {
    console.log("No Sentinel-2 images found for the specified date range and locations.");
    console.log("C1");
    return;
  }

  // Cloud mask function for Sentinel-2 SR data (SCL band)
  function maskS2clouds(image) {
    const SCL = image.select('SCL');
    // Pixels that are not cloud shadow, clouds, or cirrus.
    // 3 = vegetation, 4 = bare soil, 5 = water, 6 = unclassified, 7 = medium prob clouds, 8 = high prob clouds, 9 = cirrus, 10 = snow/ice.
    // Valid water pixels are SCL == 6 (unclassified but clear water, often), or 5 (water), excluding clouds.
    // Keep: 5 (Water), 6 (Unclassified - often clear water), 0 (No Data), 1 (Saturated or Defective), 2 (Dark Area Pixels)
    // Mask out: 3 (Vegetation), 4 (Soil), 7 (Medium Cloud), 8 (High Cloud), 9 (Cirrus), 10 (Snow/Ice)
    const valid_water = SCL.eq(5).or(SCL.eq(6)); // Filter for water or unclassified which could be water
    return image.updateMask(valid_water);
  }

  // Get the least cloudy image from the collection
  const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const image_date = await ee.Date(image.get('system:time_start')).format('YYYY-MM-dd').getInfo();
  const cloud_percentage = await image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();
  console.log(`Selected image from ${image_date} with ${cloud_percentage}% cloud cover.`);

  // Apply cloud and water mask
  const masked_image = maskS2clouds(image);

  // Select the Green band (B3)
  const green_band = masked_image.select('B3'); // B3 is the Green band

  // Define a scale for reduceRegion. 10m for S2, but we use a larger scale to be safe for point reduction.
  const scale = 10; // Use native resolution for points

  // 3. Processing & Calculation for Kornwerderzand
  const green_val_kornwerderzand_dict = await green_band.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point_kornwerderzand,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  let green_val_kornwerderzand = green_val_kornwerderzand_dict ? green_val_kornwerderzand_dict.B3 : null;

  // Check for C2 or C3
  if (green_val_kornwerderzand === null) {
    console.log("C3"); // Calculation failure for Kornwerderzand
    return;
  }

  // Check valid pixels count for Kornwerderzand
  const count_kornwerderzand_dict = await green_band.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point_kornwerderzand,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const count_kornwerderzand = count_kornwerderzand_dict ? count_kornwerderzand_dict.B3 : 0;

  if (count_kornwerderzand === 0) {
    console.log("No valid pixels for Kornwerderzand after masking.");
    console.log("C2");
    return;
  }

  // 4. Processing & Calculation for Afsluitdijk
  const green_val_afsluitdijk_dict = await green_band.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point_afsluitdijk,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  let green_val_afsluitdijk = green_val_afsluitdijk_dict ? green_val_afsluitdijk_dict.B3 : null;

  // Check for C2 or C3
  if (green_val_afsluitdijk === null) {
    console.log("C3"); // Calculation failure for Afsluitdijk
    return;
  }

  // Check valid pixels count for Afsluitdijk
  const count_afsluitdijk_dict = await green_band.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point_afsluitdijk,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();
  const count_afsluitdijk = count_afsluitdijk_dict ? count_afsluitdijk_dict.B3 : 0;

  if (count_afsluitdijk === 0) {
    console.log("No valid pixels for Afsluitdijk after masking.");
    console.log("C2");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Green reflectance (B3) near Kornwerderzand: ${green_val_kornwerderzand.toFixed(2)} (Pixels: ${count_kornwerderzand})`);
  console.log(`Green reflectance (B3) near Afsluitdijk: ${green_val_afsluitdijk.toFixed(2)} (Pixels: ${count_afsluitdijk})`);

  // "Visibly greener" implies a higher green reflectance value.
  if (green_val_kornwerderzand > green_val_afsluitdijk) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
